def calc(expr):
    s = expr
    i = 0
    n = len(s)

    def skip_spaces():
        nonlocal i
        while i < n and s[i] == ' ':
            i += 1

    def parse_number():
        nonlocal i
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    def parse_primary():
        nonlocal i
        skip_spaces()
        if i < n and s[i] == '(':
            i += 1
            val = parse_expr()
            skip_spaces()
            if i < n and s[i] == ')':
                i += 1
            return val
        else:
            return parse_number()

    def parse_factor():
        nonlocal i
        skip_spaces()
        if i < n and s[i] == '-':
            i += 1
            return -parse_factor()
        return parse_primary()

    def int_div(a, b):
        sign = 1 if (a < 0) == (b < 0) else -1
        return sign * (abs(a) // abs(b))

    def parse_term():
        nonlocal i
        val = parse_factor()
        while True:
            skip_spaces()
            if i < n and s[i] == '*':
                i += 1
                rhs = parse_factor()
                val = val * rhs
            elif i < n and s[i] == '/':
                i += 1
                rhs = parse_factor()
                val = int_div(val, rhs)
            else:
                break
        return val

    def parse_expr():
        nonlocal i
        val = parse_term()
        while True:
            skip_spaces()
            if i < n and s[i] == '+':
                i += 1
                rhs = parse_term()
                val = val + rhs
            elif i < n and s[i] == '-':
                i += 1
                rhs = parse_term()
                val = val - rhs
            else:
                break
        return val

    result = parse_expr()
    return result

